def slack_list_channels(workspace_id, types=None, status=None, is_archived=None, is_member=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, workspace_id_for_log=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"slk_rlg_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "service": "slack",
            "endpoint": "slack_list_channels",
            "workspace_id": workspace_id_for_log,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        for r in limits:
            if not isinstance(r, dict):
                continue
            if r.get("service") not in (None, "slack"):
                continue
            ep = r.get("endpoint")
            if ep not in (None, endpoint):
                continue

            per_min = r.get("per_minute")
            per_day = r.get("per_day")
            quota = r.get("quota_per_day")
            now_dt = datetime.datetime.utcnow()
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []

            def _parse_ts(s):
                if not isinstance(s, str):
                    return None
                try:
                    if s.endswith("Z"):
                        s2 = s[:-1]
                    else:
                        s2 = s
                    return datetime.datetime.fromisoformat(s2)
                except Exception:
                    return None

            ep_logs = []
            for lg in logs:
                if not isinstance(lg, dict):
                    continue
                if lg.get("service") != "slack":
                    continue
                if lg.get("endpoint") != endpoint:
                    continue
                ts = _parse_ts(lg.get("timestamp"))
                if ts is None:
                    continue
                ep_logs.append(ts)

            if isinstance(per_min, int) and per_min > 0:
                cutoff = now_dt - datetime.timedelta(minutes=1)
                used = sum(1 for ts in ep_logs if ts >= cutoff)
                if used >= per_min:
                    return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint.", limit=per_min, window_seconds=60)

            day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)
            used_today = sum(1 for ts in ep_logs if ts >= day_start)
            if isinstance(per_day, int) and per_day > 0 and used_today >= per_day:
                return _err("RATE_LIMIT", "Daily rate limit exceeded for this endpoint.", limit=per_day, window="day")
            if isinstance(quota, int) and quota > 0 and used_today >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this endpoint.", quota=quota, window="day")
        return None

    rl_err = _enforce_limits("slack_list_channels")
    if rl_err:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": rl_err["error"]["code"]})
        return rl_err

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")
        if types is not None:
            if not isinstance(types, list) or any((not isinstance(x, str)) for x in types):
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "types must be an array of strings.")
            allowed = {"public_channel", "private_channel", "im", "mpim"}
            if any(x not in allowed for x in types):
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid channel type in types.")
        if status is not None:
            if not isinstance(status, list) or any((not isinstance(x, str)) for x in status):
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "status must be an array of strings.")
            allowed = {"active", "archived", "inaccessible", "deleted"}
            if any(x not in allowed for x in status):
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid channel status in status.")
        if is_archived is not None and not isinstance(is_archived, bool):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "is_archived must be boolean.")
        if is_member is not None and not isinstance(is_member, bool):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "is_member must be boolean.")
        if search is not None and not isinstance(search, str):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "search must be a string.")
        if sort_by is not None and sort_by not in ("name", "created_at", "updated_at"):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid sort_by.")
        if sort_order is not None and sort_order not in ("asc", "desc"):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid sort_order.")
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        if cursor is not None and not isinstance(cursor, str):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a string.")
    except Exception:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid request parameters.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active" or not ws.get("oauth_access_token_ciphertext"):
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not authorized for Slack operations.")

    channels = _load("channels.json")
    if not isinstance(channels, list):
        channels = []

    rows = []
    q = search.lower() if isinstance(search, str) and search != "" else None
    for ch in channels:
        if not isinstance(ch, dict):
            continue
        if ch.get("workspace_id") != workspace_id:
            continue
        if ch.get("status") == "deleted":
            continue  # business rule
        if types is not None and ch.get("type") not in set(types):
            continue
        if status is not None and ch.get("status") not in set(status):
            continue
        if is_archived is not None and ch.get("is_archived") is not is_archived:
            continue
        if is_member is not None and ch.get("is_member") is not is_member:
            continue
        if q is not None:
            nm = ch.get("name")
            if not isinstance(nm, str) or q not in nm.lower():
                continue
        rows.append(ch)

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # default ordering: (type asc, name asc, slack_channel_id asc)
    if sort_by is None:
        def _k(ch):
            t = ch.get("type") or ""
            nm = ch.get("name")
            nm2 = nm.lower() if isinstance(nm, str) else ""
            sid = ch.get("slack_channel_id") or ""
            return (t, nm2, sid)
        rows.sort(key=_k)
    else:
        reverse = (sort_order == "desc")
        if sort_by == "name":
            def _k(ch):
                nm = ch.get("name")
                return (nm.lower() if isinstance(nm, str) else "", ch.get("slack_channel_id") or "")
        elif sort_by == "created_at":
            def _k(ch):
                dt = _parse_iso(ch.get("created_at")) or datetime.datetime.min
                return (dt, ch.get("slack_channel_id") or "")
        else:  # updated_at
            def _k(ch):
                dt = _parse_iso(ch.get("updated_at")) or datetime.datetime.min
                return (dt, ch.get("slack_channel_id") or "")
        rows.sort(key=_k, reverse=reverse)

    # Cursor: base64("offset:<int>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            else:
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    resp = {
        "channels": page,
        "pagination": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
        "total": total
    }
    _log("ok", workspace_id_for_log=workspace_id, extra={"returned": len(page)})
    return resp

def slack_post_message(workspace_id, channel_id, text, thread_root_slack_ts=None, thread_root_message_id=None, client_msg_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    _now = _now_dt.isoformat() + "Z"

    def _log(status, workspace_id_for_log=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"slk_rlg_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "service": "slack",
            "endpoint": "slack_post_message",
            "workspace_id": workspace_id_for_log,
            "credential_id": None,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        for r in limits:
            if not isinstance(r, dict):
                continue
            if r.get("service") not in (None, "slack"):
                continue
            ep = r.get("endpoint")
            if ep not in (None, endpoint):
                continue
            per_min = r.get("per_minute")
            quota = r.get("quota_per_day")
            now_dt = datetime.datetime.utcnow()
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []

            def _parse_ts(s):
                if not isinstance(s, str):
                    return None
                try:
                    if s.endswith("Z"):
                        s = s[:-1]
                    return datetime.datetime.fromisoformat(s)
                except Exception:
                    return None

            ts_list = []
            for lg in logs:
                if not isinstance(lg, dict):
                    continue
                if lg.get("service") != "slack" or lg.get("endpoint") != endpoint:
                    continue
                ts = _parse_ts(lg.get("timestamp"))
                if ts:
                    ts_list.append(ts)

            if isinstance(per_min, int) and per_min > 0:
                cutoff = now_dt - datetime.timedelta(minutes=1)
                used = sum(1 for ts in ts_list if ts >= cutoff)
                if used >= per_min:
                    return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint.", limit=per_min, window_seconds=60)

            if isinstance(quota, int) and quota > 0:
                day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)
                used_today = sum(1 for ts in ts_list if ts >= day_start)
                if used_today >= quota:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this endpoint.", quota=quota, window="day")
        return None

    rl_err = _enforce_limits("slack_post_message")
    if rl_err:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": rl_err["error"]["code"]})
        return rl_err

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")
        if not isinstance(channel_id, str) or not re.match(r"^slk_chn_[0-9A-Z]+$", channel_id):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid channel_id.")
        if not isinstance(text, str):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "text must be a string.")
        if thread_root_slack_ts is not None and not isinstance(thread_root_slack_ts, str):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "thread_root_slack_ts must be a string.")
        if thread_root_message_id is not None:
            if not isinstance(thread_root_message_id, str) or not re.match(r"^slk_msg_[0-9A-Z]+$", thread_root_message_id):
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid thread_root_message_id.")
        if client_msg_id is not None and not isinstance(client_msg_id, str):
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "client_msg_id must be a string.")
        if thread_root_slack_ts is not None and thread_root_message_id is not None:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Provide only one of thread_root_slack_ts or thread_root_message_id.")
    except Exception:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid request parameters.")

    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active" or not ws.get("oauth_access_token_ciphertext"):
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not active; posting messages is not permitted.")

    channels = _load("channels.json")
    if not isinstance(channels, list):
        channels = []
    ch = next((c for c in channels if isinstance(c, dict) and c.get("id") == channel_id), None)
    if not ch or ch.get("workspace_id") != workspace_id:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Channel not found in this workspace.")
    if ch.get("status") == "deleted":
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Channel is deleted.")
    if ch.get("status") in ("inaccessible",):
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Channel is inaccessible for posting.")
    if ch.get("is_member") is False and ch.get("type") in ("public_channel", "private_channel"):
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "App is not a member of this channel.")

    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    # Idempotency on client_msg_id (unique where not null)
    if client_msg_id:
        for m in messages:
            if not isinstance(m, dict):
                continue
            if m.get("workspace_id") == workspace_id and m.get("slack_client_msg_id") == client_msg_id and m.get("status") != "deleted":
                _log("ok", workspace_id_for_log=workspace_id, extra={"idempotent": True, "message_id": m.get("id")})
                return {"message": m}

    # Resolve thread root if provided; enforce same channel/workspace
    root_id = None
    root_slack_ts = None
    if thread_root_message_id or thread_root_slack_ts:
        root = None
        if thread_root_message_id:
            root = next((m for m in messages if isinstance(m, dict) and m.get("id") == thread_root_message_id), None)
        else:
            # resolve by (channel, slack_ts)
            root = next((m for m in messages if isinstance(m, dict) and m.get("channel_id") == channel_id and m.get("workspace_id") == workspace_id and m.get("slack_ts") == thread_root_slack_ts), None)
        if not root:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
            return _err("NOT_FOUND", "Thread root message not found.")
        if root.get("workspace_id") != workspace_id or root.get("channel_id") != channel_id:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "CONFLICT"})
            return _err("CONFLICT", "Thread root message must belong to the same workspace/channel.")
        root_id = root.get("id")
        root_slack_ts = root.get("slack_ts")
        if not root_slack_ts:
            # allow replying to a queued/unsent root: still record link by internal id
            root_slack_ts = root.get("thread_root_slack_ts")  # may still be None

    # Create queued row ONLY after passing workspace status rule (already ensured above)
    # Generate id
    def _gen_id(prefix, existing):
        s = set(x.get("id") for x in existing if isinstance(x, dict))
        for i in range(1, 10000000):
            cand = f"{prefix}{i:06d}"
            if cand not in s:
                return cand
        return f"{prefix}{int(time.time())}"

    msg_id = _gen_id("slk_msg_", messages)
    queued = {
        "id": msg_id,
        "workspace_id": workspace_id,
        "channel_id": channel_id,
        "slack_ts": None,
        "slack_client_msg_id": client_msg_id,
        "user_id": None,
        "text": text,
        "thread_root_message_id": root_id,
        "thread_root_slack_ts": (root_slack_ts if root_id or thread_root_slack_ts else None),
        "message_type": "message",
        "status": "queued",
        "failure_reason": None,
        "sent_at": None,
        "created_at": _now,
        "updated_at": _now
    }

    # Constraint: thread_root_message_id != id
    if queued["thread_root_message_id"] == queued["id"]:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "thread_root_message_id cannot equal message id.")
    # Constraint: thread_root_message_id implies thread_root_slack_ts is not null (schema)
    # In real life, internal linkage might exist without slack_ts; but schema says must not be null.
    if queued["thread_root_message_id"] is not None and queued["thread_root_slack_ts"] is None:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "CONFLICT"})
        return _err("CONFLICT", "Thread root slack_ts is not available for this root message yet.")

    # Enforce uniqueness constraints on slack_client_msg_id if set
    if client_msg_id:
        for m in messages:
            if not isinstance(m, dict):
                continue
            if m.get("workspace_id") == workspace_id and m.get("slack_client_msg_id") == client_msg_id:
                _log("ok", workspace_id_for_log=workspace_id, extra={"idempotent": True, "message_id": m.get("id")})
                return {"message": m}

    # Simulated Slack send attempt (offline): succeed if workspace active and channel not inaccessible; else fail.
    # This keeps lifecycle dynamics consistent and writes through status transitions.
    # On success: status sent, slack_ts set, sent_at set.
    # On failure: status failed, failure_reason set.
    def _make_slack_ts(now_dt):
        base = int(now_dt.timestamp())
        micro = int((now_dt.timestamp() - base) * 1_000_000)
        return f"{base}.{micro:06d}"

    # Before persisting, ensure uniqueness on (workspace_id, channel_id, slack_ts) where slack_ts not null
    # We'll assign ts for success and check.
    will_succeed = True
    failure_reason = None
    if ws.get("status") != "active":
        will_succeed = False
        failure_reason = "workspace_not_active"
    if ch.get("status") in ("inaccessible", "deleted"):
        will_succeed = False
        failure_reason = "channel_inaccessible"

    if will_succeed:
        slack_ts = _make_slack_ts(_now_dt)
        # ensure uniqueness by bumping micro part if conflict
        existing_ts = set(
            m.get("slack_ts") for m in messages
            if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("channel_id") == channel_id and m.get("slack_ts") is not None
        )
        bump = 0
        while slack_ts in existing_ts and bump < 1000:
            bump += 1
            slack_ts = f"{int(_now_dt.timestamp())}.{(int((_now_dt.timestamp()-int(_now_dt.timestamp()))*1_000_000)+bump)%1_000_000:06d}"
        if slack_ts in existing_ts:
            # cannot satisfy uniqueness
            will_succeed = False
            failure_reason = "slack_ts_conflict"

    messages.append(queued)
    _save("messages.json", messages)

    # Apply transition from queued -> sent/failed
    # Load again to ensure we mutate persisted row
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []
    idx = next((i for i, m in enumerate(messages) if isinstance(m, dict) and m.get("id") == msg_id), None)
    if idx is None:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Created message not found.")

    mrow = messages[idx]
    if will_succeed:
        mrow["status"] = "sent"
        mrow["slack_ts"] = slack_ts
        mrow["sent_at"] = _now
        mrow["failure_reason"] = None
        mrow["updated_at"] = _now
    else:
        mrow["status"] = "failed"
        mrow["failure_reason"] = failure_reason or "slack_api_error"
        mrow["updated_at"] = _now

    # Enforce constraint: status sent implies slack_ts not null
    if mrow["status"] == "sent" and not mrow.get("slack_ts"):
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "CONFLICT"})
        return _err("CONFLICT", "Cannot mark message sent without slack_ts.")

