                return {"reaction": r}

    # Workspace status rule: already enforced, so we can create queued row now.
    def _gen_id(prefix, existing):
        s = set(x.get("id") for x in existing if isinstance(x, dict))
        for i in range(1, 10000000):
            cand = f"{prefix}{i:06d}"
            if cand not in s:
                return cand
        return f"{prefix}{int(time.time())}"

    rid = _gen_id("slk_rct_", reactions)
    queued = {
        "id": rid,
        "workspace_id": workspace_id,
        "message_id": message_id,
        "channel_id": channel_id,
        "emoji": emoji,
        "reacting_user_id": reacting_user_id,
        "status": "queued",
        "failure_reason": None,
        "applied_at": None,
        "created_at": _now,
        "updated_at": _now
    }

    # Simulated Slack attempt
    will_succeed = True
    failure_reason = None
    if ch.get("status") in ("inaccessible", "deleted"):
        will_succeed = False
        failure_reason = "channel_inaccessible"
    if ws.get("status") != "active":
