        failure_reason = "workspace_not_active"
    if msg.get("slack_ts") is None and msg.get("status") != "sent":
        # Can't apply reaction without a Slack message reference
        will_succeed = False
        failure_reason = "message_not_sent"

    reactions.append(queued)
    _save("reactions.json", reactions)

    # Transition queued -> applied/failed
    reactions = _load("reactions.json")
    if not isinstance(reactions, list):
        reactions = []
    idx = next((i for i, r in enumerate(reactions) if isinstance(r, dict) and r.get("id") == rid), None)
    if idx is None:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "NOT_FOUND"})
        return _err("NOT_FOUND", "Created reaction not found.")

    rrow = reactions[idx]
    if will_succeed:
        rrow["status"] = "applied"
        rrow["applied_at"] = _now
        rrow["failure_reason"] = None
        rrow["updated_at"] = _now
    else:
        rrow["status"] = "failed"
        rrow["failure_reason"] = failure_reason or "slack_api_error"
        rrow["updated_at"] = _now

    # Re-check uniqueness constraint for reacting_user_id not null and status != removed
    if rrow.get("reacting_user_id") is not None and rrow.get("status") != "removed":
        key = (rrow.get("message_id"), rrow.get("emoji"), rrow.get("reacting_user_id"))
        seen = 0
        for rr in reactions:
            if not isinstance(rr, dict):
                continue
            if (rr.get("message_id"), rr.get("emoji"), rr.get("reacting_user_id")) == key and rr.get("status") != "removed":
                seen += 1
        if seen > 1:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "CONFLICT"})
            return _err("CONFLICT", "Duplicate reaction exists for this user/message/emoji.")

    _save("reactions.json", reactions)
    _log("ok", workspace_id_for_log=workspace_id, extra={"reaction_id": rid, "status": rrow.get("status")})
    return {"reaction": rrow}

