        if not re.match(r"^\d{1,12}\.\d{1,6}$", ts):
            return "BAD"
        try:
            a, b = ts.split(".", 1)
            return (int(a), int(b.ljust(6, "0")[:6]))
        except Exception:
            return "BAD"

    try:
        if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
