            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid channel_id.")
        if latest_slack_ts is not None and _parse_slack_ts(latest_slack_ts) == "BAD":
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Malformed latest_slack_ts.")
        if oldest_slack_ts is not None and _parse_slack_ts(oldest_slack_ts) == "BAD":
