    if oldest_key == "BAD" or latest_key == "BAD":
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Malformed slack_ts bound.")
    if oldest_key and latest_key and oldest_key > latest_key:
        _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "oldest_slack_ts cannot be greater than latest_slack_ts.")

