        # filter by slack_ts bounds (queued items have slack_ts None; they won't match ts bounds if provided)
        ts = m.get("slack_ts")
        if ts is not None:
            key = _parse_slack_ts(ts)
            if key == "BAD":
                continue
            if oldest_key and key < oldest_key:
                continue
            if latest_key and key > latest_key:
