        except Exception:
            return None

    order = sort_order or "desc"
    if order == "desc":
        # order by slack_ts desc; queued by created_at desc
        def _k(m):
            ts = m.get("slack_ts")
            if isinstance(ts, str):
                key = _parse_slack_ts(ts)
                if key != "BAD":
                    return (1, key[0], key[1])
            dt = _parse_iso(m.get("created_at")) or datetime.datetime.min
            return (0, int(dt.timestamp()), 0)
        rows.sort(key=_k, reverse=True)
    else:
        # asc: slack_ts asc; queued by created_at asc at start
        def _k(m):
