        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            else:
                _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            _log("error", workspace_id_for_log=workspace_id, extra={"error": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    resp = {
        "messages": page,
        "pagination": {"limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
        "total": total
    }
    _log("ok", workspace_id_for_log=workspace_id, extra={"returned": len(page)})
    return resp

def slack_get_thread_replies(workspace_id, channel_id, thread_root_slack_ts=None, thread_root_message_id=None, include_root=None, include_deleted=None, limit=None, cursor=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "slack_get_thread_replies"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, workspace_id_used=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "slack",
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(wsp_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            try:
                if r.get("service") != "slack":
                    continue
                if r.get("workspace_id") != wsp_id:
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if dt >= window:
                    cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    def _decode_cursor(cur):
        # Relaxed: accept vendor cursor OR treat any opaque cursor as "start from 0"
        if cur in (None, ""):
            return 0
        if not isinstance(cur, str):
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4)).decode("utf-8")
            if raw.startswith("idx:"):
                idx = int(raw.split(":", 1)[1])
                return idx if idx >= 0 else 0
        except Exception:
            return 0
        return 0

    def _encode_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
        _log("error", workspace_id_used=None, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(channel_id, str) or not re.match(r"^slk_chn_[0-9A-Z]+$", channel_id):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid channel_id.")
    if thread_root_message_id is not None and (not isinstance(thread_root_message_id, str) or not re.match(r"^slk_msg_[0-9A-Z]+$", thread_root_message_id)):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid thread_root_message_id.")
    if thread_root_slack_ts is not None and not isinstance(thread_root_slack_ts, str):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid thread_root_slack_ts.")
    if include_root is None:
        include_root = False
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_root, bool) or not isinstance(include_deleted, bool):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_root and include_deleted must be boolean.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid limit.")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort_order.")

    rl = _enforce_rate_limit(workspace_id)
    if rl:
        _log("error", workspace_id_used=workspace_id, extra={"code": rl["error"]["code"]})
        return rl

    workspaces = _load("workspaces.json")
    channels = _load("channels.json")
    messages = _load("messages.json")

    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(channels, list):
        channels = []
    if not isinstance(messages, list):
        messages = []

    wsp = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not wsp:
        _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")
    # Read endpoint: do not enforce workspace active; access is ambient and workspace existence is enough.

    ch = next((c for c in channels if c.get("id") == channel_id and c.get("workspace_id") == workspace_id), None)
    if not ch:
        _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Channel not found in workspace.")

    # Resolve root
    root = None
    if thread_root_message_id is not None:
        cand = next((m for m in messages if m.get("id") == thread_root_message_id), None)
        if cand and cand.get("workspace_id") == workspace_id and cand.get("channel_id") == channel_id:
            root = cand
        else:
            # If id provided but not resolvable within channel/workspace, treat as not found
            _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Thread root message not found in the specified channel/workspace.")
    elif thread_root_slack_ts is not None:
        # Find by slack_ts in this channel/workspace (any status, including deleted, allowed as root)
        root = next(
            (m for m in messages
             if m.get("workspace_id") == workspace_id and m.get("channel_id") == channel_id and m.get("slack_ts") == thread_root_slack_ts),
            None
        )
        if not root:
            _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Thread root message not found in the specified channel/workspace.")
    else:
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Either thread_root_slack_ts or thread_root_message_id must be provided.")

    root_slack_ts = root.get("slack_ts")
    root_id = root.get("id")

    # Collect replies: root + messages that reference root by id OR by slack thread ts
    def _is_reply(m):
        if m.get("workspace_id") != workspace_id or m.get("channel_id") != channel_id:
            return False
        if m.get("id") == root_id:
            return False
        if not include_deleted and m.get("status") == "deleted":
            return False
        if m.get("thread_root_message_id") == root_id:
            return True
        if root_slack_ts and m.get("thread_root_slack_ts") == root_slack_ts:
            return True
        return False

    replies = [m for m in messages if _is_reply(m)]

    # Order by slack_ts asc/desc; items without slack_ts (queued) use created_at as tie-breaker
    def _ts_key(m):
        ts = m.get("slack_ts")
        if isinstance(ts, str):
            try:
                return (0, float(ts))
            except Exception:
                return (0, 0.0)
        # queued/undelivered: order after delivered in asc; before delivered in desc? Slack doesn't have these,
        # but rule says created_at desc for queued in history. For thread replies, keep deterministic:
        ca = m.get("created_at")
        try:
            dt = datetime.datetime.fromisoformat(str(ca).replace("Z", "+00:00"))
            epoch = dt.timestamp()
        except Exception:
            epoch = 0.0
        return (1, epoch)

    reverse = (sort_order == "desc")
    replies.sort(key=_ts_key, reverse=reverse)

    items = []
    if include_root:
        if include_deleted or root.get("status") != "deleted":
            items.append(root)

    # Apply retention max (per request). Use 1000 hard cap.
    retention_cap = 1000
    replies = replies[:retention_cap]

    start = _decode_cursor(cursor)
    if start < 0:
        start = 0

    page = replies[start:start + limit]
    items.extend(page)

    next_idx = start + len(page)
    has_more = next_idx < len(replies)
    next_cursor = _encode_cursor(next_idx) if has_more else None

    _log("ok", workspace_id_used=workspace_id, extra={"returned": len(items), "has_more": has_more})
    return {
        "ok": True,
        "workspace_id": workspace_id,
        "channel_id": channel_id,
        "thread_root_message_id": root_id,
        "thread_root_slack_ts": root_slack_ts,
        "messages": items,
        "pagination": {
            "limit": limit,
            "cursor": next_cursor,
            "has_more": has_more,
            "total_replies": len(replies),
            "returned": len(items),
        },
        "sort_order": sort_order,
        "include_root": include_root,
        "include_deleted": include_deleted,
    }

def slack_get_users(workspace_id, include_deleted=None, is_bot=None, search=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
