            if not raw.startswith("idx:"):
                return None
            idx = int(raw.split(":", 1)[1])
            if idx < 0:
                return None
            return idx
        except Exception:
            return None

    def _make_cursor(idx):
        raw = f"idx:{idx}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log(status, workspace_id_used=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "slack",
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(wsp_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            try:
                if r.get("service") != "slack":
                    continue
                if r.get("workspace_id") != wsp_id:
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if dt >= window:
                    cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
        _log("error", workspace_id_used=None, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")
    if is_bot is not None and not isinstance(is_bot, bool):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "is_bot must be a boolean.")
    if search is not None and not isinstance(search, str):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "search must be a string.")
    if sort_by is not None and sort_by not in ("username", "display_name", "real_name", "created_at", "updated_at"):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort_by.")
    if sort_order is not None and sort_order not in ("asc", "desc"):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort_order.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")
    idx = _parse_cursor(cursor)
    if idx is None:
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    rl = _enforce_rate_limit(workspace_id)
    if rl:
        _log("error", workspace_id_used=workspace_id, extra={"code": "RATE_LIMIT"})
        return rl

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", workspace_id_used=workspace_id, extra={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Caller cannot access the workspace.")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    inc_del = bool(include_deleted) if include_deleted is not None else False

    filtered = []
    q = search.lower() if isinstance(search, str) and search else None

    for u in users:
        if u.get("workspace_id") != workspace_id:
            continue

        # Business rule: is_deleted=true must return status='deleted'
        if u.get("is_deleted") is True and u.get("status") != "deleted":
            # do not mutate on read; just present corrected view
            u = dict(u)
            u["status"] = "deleted"

        if not inc_del and u.get("status") in ("deleted", "deactivated"):
            continue
        if is_bot is not None and u.get("is_bot") is not is_bot:
            continue
        if q:
            hay = " ".join([
                str(u.get("username") or ""),
                str(u.get("display_name") or ""),
                str(u.get("real_name") or ""),
                str(u.get("email") or ""),
            ]).lower()
            if q not in hay:
                continue
        filtered.append(u)

    sb = sort_by or "created_at"
    so = sort_order or "asc"

    def _sort_key(u):
        v = u.get(sb)
        if v is None:
            return (1, "")
        return (0, str(v).lower() if isinstance(v, str) else str(v))

    filtered.sort(key=_sort_key, reverse=(so == "desc"))

    total = len(filtered)
    page = filtered[idx: idx + limit]
    next_idx = idx + len(page)
    has_more = next_idx < total
    next_cursor = _make_cursor(next_idx) if has_more else None

    resp = {
        "users": page,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total
        }
    }
    _log("ok", workspace_id_used=workspace_id, extra={"returned": len(page)})
    return resp

def slack_get_user_profile(workspace_id, user_id=None, slack_user_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "slack_get_user_profile"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now().isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            # accept "Z" and offsets; normalize to naive UTC-ish
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status, workspace_id_used=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "slack",
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(wsp_id):
        # Simple per-workspace limit: 120 requests/minute
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("service") != "slack":
                continue
            if r.get("workspace_id") != wsp_id:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt is not None and dt >= window:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    # ---------------- Validation ----------------
    try:
        if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id or ""):
            _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")
        if user_id is not None:
            if not isinstance(user_id, str) or not re.match(r"^slk_usr_[0-9A-Z]+$", user_id or ""):
                _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid user_id.")
        if slack_user_id is not None:
            if not isinstance(slack_user_id, str) or len(slack_user_id.strip()) == 0:
                _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid slack_user_id.")
        if user_id is None and slack_user_id is None:
            _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Either user_id or slack_user_id must be provided.")
    except Exception:
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid parameters.")

    # --------------- Authorization / context ---------------
    # Ambient auth: authorize if ANY workspace exists with this id (and is connected enough to serve reads).
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    wsp = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            wsp = w
            break
    if wsp is None:
        _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Workspace not found.")

    # Reads are allowed even if suspended/revoked (business rule only blocks mutating operations).
    # However, still require that the installation is usable for profile fetch semantics.
    if wsp.get("oauth_access_token_ciphertext") in (None, ""):
        _log("error", workspace_id_used=workspace_id, extra={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Workspace is not connected to Slack.")

    rl = _enforce_rate_limit(workspace_id)
    if rl is not None:
        _log("error", workspace_id_used=workspace_id, extra={"code": rl["error"]["code"]})
        return rl

    users = _load("users.json")
    if not isinstance(users, list):
        users = []

    # --------------- Resolve user (relaxed matching) ---------------
    # The audit defect indicates callers may pass both ids that don't match; accept if either resolves.
    # Preference: if user_id resolves in workspace, use it; else if slack_user_id resolves, use that.
    resolved = None
    by_user_id = None
    by_slack_id = None

    if user_id is not None:
        for u in users:
            if isinstance(u, dict) and u.get("id") == user_id and u.get("workspace_id") == workspace_id:
                by_user_id = u
                break
    if slack_user_id is not None:
        for u in users:
            if isinstance(u, dict) and u.get("slack_user_id") == slack_user_id and u.get("workspace_id") == workspace_id:
                by_slack_id = u
                break

    if by_user_id is not None:
        resolved = by_user_id
    elif by_slack_id is not None:
        resolved = by_slack_id
    else:
        _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "User not found in this workspace.")

    # --------------- Enforce business rule: is_deleted => status='deleted' ---------------
    now_iso = _now_iso()
    changed = False

    if bool(resolved.get("is_deleted")) and resolved.get("status") != "deleted":
        # lifecycle allows active/deactivated -> deleted; but this is a derived state to satisfy read rule
        resolved["status"] = "deleted"
        changed = True

    # "On fetch it refreshes users.* profile fields and sets last_profile_fetch_at = now()."
    # Offline implementation: we can only update timestamps and updated_at; do not fabricate profile values.
    resolved["last_profile_fetch_at"] = now_iso
    resolved["updated_at"] = now_iso
    changed = True

    if changed:
        # Persist back the modified user row
        for i, u in enumerate(users):
            if isinstance(u, dict) and u.get("id") == resolved.get("id"):
                users[i] = resolved
                break
        _save("users.json", users)

    # Return envelope
    resp = {
        "workspace_id": workspace_id,
        "user": resolved,
    }
    _log("ok", workspace_id_used=workspace_id)
    return resp

def slack_get_channel(workspace_id, channel_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "slack_get_channel"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, workspace_id_used=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "service": "slack",
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(wsp_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            try:
                if r.get("service") != "slack":
                    continue
                if r.get("workspace_id") != wsp_id:
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                if dt >= window:
                    cnt += 1
            except Exception:
                continue
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    if not isinstance(workspace_id, str) or not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
        _log("error", workspace_id_used=None, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(channel_id, str) or not re.match(r"^slk_chn_[0-9A-Z]+$", channel_id):
        _log("error", workspace_id_used=workspace_id, extra={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid channel_id.")

    rl = _enforce_rate_limit(workspace_id)
    if rl:
        _log("error", workspace_id_used=workspace_id, extra={"code": "RATE_LIMIT"})
        return rl

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if ws is None:
        _log("error", workspace_id_used=workspace_id, extra={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Caller cannot access the workspace.")

    channels = _load("channels.json")
    if not isinstance(channels, list):
        channels = []
    ch = next((c for c in channels if c.get("id") == channel_id and c.get("workspace_id") == workspace_id), None)
    if ch is None or ch.get("status") == "deleted":
        _log("error", workspace_id_used=workspace_id, extra={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Channel not found in workspace.")

    _log("ok", workspace_id_used=workspace_id, extra={"channel_id": channel_id})
    return {"channel": ch}

def slack_get_auth_context(workspace_id=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_reqlog():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(endpoint, status, workspace_id_used=None, credential_id=None, latency_ms=None, error_code=None):
        if not _ensure_reqlog():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "slack_get_auth_context"

    # Validate inputs
    if workspace_id is not None:
        if not isinstance(workspace_id, str):
            _log(endpoint, "error", None, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must be a string")
        if not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
            _log(endpoint, "error", None, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id does not match required pattern")

    # Ambient auth resolution: choose a workspace that can serve calls (active workspace with token/scopes).
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    candidates = []
    for w in workspaces:
        if not isinstance(w, dict):
            continue
        if workspace_id is not None and w.get("id") != workspace_id:
            continue
        # "working combination": has an access token ciphertext (presence indicates installation in this store)
        if w.get("oauth_access_token_ciphertext") and w.get("status") in ("active", "suspended", "revoked"):
            candidates.append(w)

    if not candidates:
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized workspace context available for this request")

    # Prefer active workspaces when not explicitly scoped
    resolved = None
    if workspace_id is not None:
        resolved = candidates[0]
    else:
        for w in candidates:
            if w.get("status") == "active":
                resolved = w
                break
        if resolved is None:
            resolved = candidates[0]

    # Rate/quota: schema doesn't declare a usage collection/counters for enforcement.
    # Provide consumption as best-effort from request_logs if present, but do not enforce.
    usage = {
        "rate_limit": None,
        "quota": None,
    }
    if os.path.exists(os.path.join(_DB, "request_logs.json")):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            now = datetime.datetime.utcnow()
            window_start = now - datetime.timedelta(minutes=1)
            day_start = now - datetime.timedelta(days=1)
            per_min = 0
            per_day = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("workspace_id") != resolved.get("id"):
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= window_start:
                    per_min += 1
                if dt >= day_start:
                    per_day += 1
            usage = {
                "rate_limit": {"window_seconds": 60, "requests_in_window": per_min, "limit": None},
                "quota": {"window_seconds": 86400, "requests_in_window": per_day, "limit": None},
            }

    body = {
        "workspace": resolved,
        "scopes": resolved.get("scopes") if isinstance(resolved.get("scopes"), list) else [],
        "usage": usage,
    }

    _log(endpoint, "ok", resolved.get("id"), None, int((time.time() - t0) * 1000), None)
    return body

def slack_update_workspace_status(workspace_id, status, reason=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0252000" if __import__("os").path.isdir("./environment_mix/0252000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_reqlog():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            try:
                _save("request_logs.json", [])
            except Exception:
                return False
        return True

    def _log(endpoint, status_s, workspace_id_used=None, credential_id=None, latency_ms=None, error_code=None):
        if not _ensure_reqlog():
            return
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "workspace_id": workspace_id_used,
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "slack_update_workspace_status"

    # Validate inputs
    if not isinstance(workspace_id, str):
        _log(endpoint, "error", None, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a string")
    if not re.match(r"^slk_wsp_[0-9A-Z]+$", workspace_id):
        _log(endpoint, "error", None, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id does not match required pattern")

    if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")

    if reason is not None and not isinstance(reason, str):
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string if provided")

    # Ambient auth: caller must be able to "manage" the workspace.
    # No explicit ACL/credential collections exist in schema; treat existence of workspace installation as authorization.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []

    idx = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            idx = i
            break

    if idx is None:
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    ws = workspaces[idx]
    if not ws.get("oauth_access_token_ciphertext"):
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Caller is not authorized to manage this workspace")

    current = ws.get("status")
    if current not in ("active", "suspended", "revoked"):
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Workspace has invalid current status in datastore")

    transitions = {
        "active": ["revoked", "suspended"],
        "suspended": ["active", "revoked"],
        "revoked": [],
    }

    if status == current:
        # Idempotent update: no state change, but it's a valid request; update audit timestamp/note only if provided.
        changed = False
        if reason is not None and reason.strip() != "":
            ws["status_change_reason"] = reason
            ws["status_changed_at"] = _now_iso()
            changed = True
        ws["updated_at"] = _now_iso()
        workspaces[idx] = ws
        _save("workspaces.json", workspaces)
        _log(endpoint, "ok", workspace_id, None, int((time.time() - t0) * 1000), None)
        return {"workspace": ws, "changed": changed}

    if status not in transitions.get(current, []):
        _log(endpoint, "error", workspace_id, None, int((time.time() - t0) * 1000), "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "Illegal workspace status transition",
            from_status=current,
            to_status=status,
            allowed=transitions.get(current, []),
        )

    ws["status"] = status
    ws["updated_at"] = _now_iso()
    ws["status_changed_at"] = _now_iso()
    if reason is not None and reason.strip() != "":
        ws["status_change_reason"] = reason

    workspaces[idx] = ws
    _save("workspaces.json", workspaces)

    _log(endpoint, "ok", workspace_id, None, int((time.time() - t0) * 1000), None)
    return {"workspace": ws, "changed": True}
